from lesson_authoring import entry as E
from author_batch200_root_nomen_a import B
W=[
E('noun','/naʊn/','名词','给人、地方、事物或概念一个名称的那类词。','经英法语 noun／non，来自拉丁 nomen“名称、名词”；语法名称沿着“给东西命名”发展，字形经过法语变化。',[['拉丁 nomen → 英法语 noun／non','名字、名词'],['英语 noun','名词这一词类']],'table、river 是具体事物的名词，freedom、arrival 也可以是名词，虽然摸不着。判断词类不能只看有没有实物，更要看句中用法；同一个拼写如 work 可以在不同句子里当名词或动词。','a countable noun；an uncountable noun；a proper noun；a noun phrase。','noun 是词类，subject 是句子成分。名词能作主语，也能作宾语等，不能把名词和主语画等号。',('In this sentence, work is a noun rather than a verb.','在这个句子里，work 是名词，不是动词。'),('Freedom is an abstract noun.','freedom 是一个抽象名词。'),sources=['https://www.etymonline.com/word/noun','https://en.wiktionary.org/wiki/noun']),
E('pronoun','英 /ˈprəʊnaʊn/；美 /ˈproʊnaʊn/','代词','用 I、you、she、it 等词指人或物，不必每次重复完整名称。','来自法语 pronom／pronon 与拉丁 pronomen，pro-“代替”+ nomen“名词”；英语形式受 noun 影响。现代可联系 pro- + noun，但历史并非只有英语内拼接。',[['拉丁 pro- + nomen → pronomen','代替名词的词'],['法语 pronom 等 → 英语 pronoun','形式受 noun 影响 → 代词']],'Maya arrived. She sat down. 中的 she 指向 Maya，省去重复名字。I、you 也可直接指说话者和听者，不一定在前文有一个名词等着替换。因此“代替名词”是入门画面，不是所有代词用法的完整定义。','a personal pronoun；a reflexive pronoun；a relative pronoun；use the pronoun。','noun 常给事物一个名称，pronoun 常依赖说话场景或上下文来指称。代词指向不明，会让读者不知道谁做了什么。',('The pronoun it refers to the old bridge in the previous sentence.','代词 it 指的是前一句中的那座旧桥。'),('Rewrite the sentence so that each pronoun has a clear reference.','改写这个句子，让每个代词的指向都清楚。'),sources=['https://www.etymonline.com/word/pronoun','https://en.wiktionary.org/wiki/pronoun']),
E('nominative','英 /ˈnɒmɪnətɪv/；美 /ˈnɑːmɪnətɪv/','主格；主格的〔语法〕','某些语言中，词在主语位置常用的格形式。','经法语 nominatif 或直接接拉丁 nominativus“用于命名的”，出自 nominare；在 casus nominativus 中成为语法格名。',B+[['拉丁 nominativus／法语 nominatif → 英语 nominative','用于命名的格 → 主格']],'英语的 she 与 her、I 与 me 能帮助看出主格和宾格差别：She called me 中 she 是主语形式。普通英语名词通常不再靠不同词尾标主格；学习拉丁语、德语等语言时，会更常遇到这个术语。','the nominative case；a nominative pronoun；in the nominative。','nominative 是主格，accusative 常是宾格；nomination 是提名，与语法格不是同一件事。',('In She called me, she is in the nominative case.','在 She called me 中，she 用的是主格。'),('The exercise asks students to identify the nominative form of each pronoun.','练习要求学生辨认每个代词的主格形式。'),sources=['https://www.etymonline.com/word/nominative','https://en.wiktionary.org/wiki/nominative']),
E('nominalization','英 /ˌnɒmɪnəlaɪˈzeɪʃən/；美 /ˌnɑːmɪnələˈzeɪʃən/','名词化','把一个动作或性质包装成名词，方便当作一个概念来谈。','nominal 的名词相关义 + -ization，或 nominalize + -ation；不是 nominal“仅名义上的”在这里表示假装行动。',[['拉丁 nomen → nominalis → 英语 nominal','名字、名词 → 名词相关的'],['英语 nominalize／nominal + -ization → nominalization','使成为名词 → 名词化']],'把 decide“决定”换成 decision“决定这一事项”，就是一个容易理解的例子。名词化能把动作当成讨论对象，但连续堆叠也可能让句子变得绕。它本身不是语法错误，要看是否有助于表达。','use nominalization；excessive nominalization；a nominalization of a verb。','nominalization 是构成或使用名词形式，nomination 是提名；两者共享名字的远源，现代术语不同。',('Decision is a nominalization related to the verb decide.','decision 是与动词 decide 对应的名词化形式。'),('The editor reduced unnecessary nominalization to make the report clearer.','编辑减少了不必要的名词化表达，让报告更清楚。'),sources=['https://en.wiktionary.org/wiki/nominalization']),
E('nominal','英 /ˈnɒmɪnəl/；美 /ˈnɑːmɪnəl/','名义上的；象征性的、很少的；名词的；标称的','名称或牌面上是这样，实际情况可能另算；收费时也可只收象征性的一点。','来自拉丁 nominalis“名称的”，接 nomen／nominis；从名称相关，发展为仅在名称上成立，再到象征性金额等用法。',[['拉丁 nomen → nominalis','名字 → 名称相关的'],['英语 nominal','名词的；名义上的；象征性或标称的']],'a nominal leader 可能有头衔却没实权；a nominal fee 是象征性的小额费用，不是根本没收费。设备的 nominal value 是标称值，实际测量可能有允许偏差。共同点是关注名称、标定或形式上的量，而非每次都暗示骗人。','a nominal fee；a nominal leader；nominal control；a nominal value；nominal forms。','nominal 不等于 normal“正常的”。名义、标称与实际的差别需看语境；象征性费用通常是很少，不是零。',('Visitors pay only a nominal fee to enter the garden.','游客只需支付一小笔象征性费用就能进入花园。'),('He was the nominal leader, but the committee made the decisions.','他是名义上的负责人，实际由委员会作决定。'),sources=['https://www.etymonline.com/word/nominal','https://www.oxfordlearnersdictionaries.com/definition/english/nominal','https://en.wiktionary.org/wiki/nominal']),
E('nominally','英 /ˈnɒmɪnəli/；美 /ˈnɑːmɪnəli/','名义上、形式上；按标称值','如果只看名称或正式安排，是这样；实际运作还得再看。','nominal + -ly，形容词变副词；主要保留名义上或标定数值上的意思。',[['拉丁 nomen → nominalis → 英语 nominal','名称 → 名义或标称的'],['英语 nominal → nominally','名义上；按标称数值']],'nominally independent 是名义上独立，作者往往接着说明实际受谁影响。a nominally twelve-volt system 说的是系统标称电压，不保证任何时刻测到的数字都完全相同。不要把 nominally 与 normally“通常”混写。','nominally independent；nominally in charge；nominally equal；nominally rated。','nominally 是按名称、形式或标称，normally 是通常、正常情况下；只差几个字母，却会改变整句判断。',('She was nominally in charge, but had little control over the budget.','她名义上负责，却几乎无权支配预算。'),('The two roles are nominally equal, though their responsibilities differ.','这两个职位名义上平级，但职责不同。'),sources=['https://en.wiktionary.org/wiki/nominally','https://www.etymonline.com/word/nominally'])]
